/**
 * ImageRequest
 */
export type ApiRoutesV1ImagesEditsImageRequest = {
  /**
   * Aspect
   */
  aspect?: '1:1' | '4:3' | '3:4' | '16:9'
  /**
   * Batch Collection Target
   *
   * Expected image count in the submitting cohort. Only shortens collection waiting; queued compatible requests may still share a larger admitted batch.
   */
  batch_collection_target?: number | null
  /**
   * Count
   */
  count?: 1 | 2 | 4
  /**
   * Height
   */
  height?: number | null
  /**
   * Image
   *
   * PNG data URL, at most 20 MiB. Dimensions must be multiples of 32, at most 3072 per side and 4,718,592 pixels. Reference inputs must contain at least 65,536 pixels. Source mode uses the source dimensions; reference mode accepts an independent target width and height.
   */
  image: string
  /**
   * Mask
   *
   * Opaque PNG matching the source size. Black preserves pixels, white edits them; gray blends.
   */
  mask?: string | null
  /**
   * Mode
   *
   * Source edits noise the input image. Reference edits generate a new image conditioned on one or more reference images.
   */
  mode?: 'source' | 'reference'
  /**
   * Model Id
   */
  model_id?: 'flux.2-klein-4b' | null
  /**
   * Prompt
   */
  prompt: string
  /**
   * Reference Images
   *
   * Optional additional PNG reference data URLs for reference mode, ordered after image (up to 4 total references).
   */
  reference_images?: Array<string> | null
  /**
   * Seed
   */
  seed?: number | null
  /**
   * Steps
   */
  steps?: number
  /**
   * Strength
   *
   * Image-to-image noise strength. Zero preserves the source; one regenerates the editable area from noise. Describe the desired result in prompt.
   */
  strength?: number
  /**
   * Width
   */
  width?: number | null
}

/**
 * ImageRequest
 */
export type ApiRoutesV1ImagesGenerationsImageRequest = {
  /**
   * Aspect
   */
  aspect?: '1:1' | '4:3' | '3:4' | '16:9'
  /**
   * Batch Collection Target
   *
   * Expected image count in the submitting cohort. Only shortens collection waiting; queued compatible requests may still share a larger admitted batch.
   */
  batch_collection_target?: number | null
  /**
   * Count
   */
  count?: 1 | 2 | 4
  /**
   * Model Id
   *
   * Omit to use the image model selected in Settings.
   */
  model_id?: 'flux.2-klein-4b' | null
  /**
   * Prompt
   */
  prompt: string
  /**
   * Provider
   *
   * Omit to use the image provider in Settings. Local explicitly preserves native generation, including pet stages.
   */
  provider?: 'local' | null
  /**
   * Seed
   */
  seed?: number | null
  /**
   * Steps
   *
   * Inference step count. FLUX.2 Klein 4B Distilled uses its fixed four-step schedule.
   */
  steps?: number
}

